// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        bool result1;
        bool result2;
        vm.prank(caller1);
        result1 = c.paused();
        vm.prank(caller2);
        result2 = c.paused();
        assertTrue(result1 == result2);
    }
}
